   501  void VC5Decompressor::Wavelet::LowPassBand::decode(const Wavelet& wavelet) {
   502    data = Array2DRef<int16_t>::create(wavelet.width, wavelet.height);
   503    const Array2DRef<int16_t> dst(data.data(), wavelet.width, wavelet.height);
   504
   505    BitPumpMSB bits(bs);
   506    for (auto row = 0U; row < dst.height; ++row) {
   507      for (auto col = 0U; col < dst.width; ++col)
   508        dst(col, row) = static_cast<int16_t>(bits.getBits(lowpassPrecision));
   509    }
   510  }
